    # Reverse the digits
    reversed_p = int(str(p)[::-1])
    # Check if reversed number is also prime
    if is_prime(reversed_p):
        reversible_primes.append((p, reversed_p))

print(f"Primes that remain prime when reversed: {reversible_primes}")

# Calculate the sum
total_sum = sum(p for p, _ in reversible_primes)
print(f"Sum: {total_sum}")

